def _post_trust_presentations_consume(self, tenant: str) -> None:
    # POST /v1/trust/presentations/consume：验真并一次性消费
    # 跨系统外部演示（防重放）。
    # 1) 请求体解析、字段约束与验真规则完全沿用
    #    /v1/trust/presentations/verify：未绑定恰含
    #    presentation/challenge；持有者绑定另恰含非空
    #    source_tenant_id，演示恰为绑定十二字段，双锚点双签名、
    #    期限、校验顺序与 reason 全部一致；任何验真失败均
    #    HTTP 200 按键序仅返 {"valid":false,"reason":...}，不
    #    写消费标记、不记审计；显式空 X-Tenant-ID 在进入前由
    #    路由统一判 400；
    # 2) 验真成功后按租户以 (issuer_did, presentation_id) 为
    #    唯一键消费：首次 200 按序恰返 valid、consumption_id、
    #    consumed_at（valid:true；consumption_id 为请求规范化
    #    JSON 字节的 SHA-256 小写 64 位 hex；consumed_at 为
    #    UTC 秒精度 Z）；同键重放（演示内容可不同）或并发均
    #    200 仅返 {"valid":false,"reason":"外部演示已消费"}，
    #    每键仅一次成功；
    # 3) 首次消费标记与审计（trust.presentation.consumed /
    #    trust_presentation / consumption_id）同一次原子写落盘；
    #    重放与验真失败不记；落盘失败回滚二者，500 仅返
    #    {"error":"存储失败"}，可重试；按租户隔离，跨重启仍
    #    判重。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_invalid("请求体缺失或长度声明非法")
        return
    except Exception:  # noqa: BLE001
        self._send_invalid("请求体读取失败")
        return
    if not raw:
        self._send_invalid("请求体缺失")
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_invalid("请求体不是合法 UTF-8 文本")
        return
    except json.JSONDecodeError:
        self._send_invalid("请求体不是合法 JSON")
        return

    try:
        valid, reason = store.verify_trust_presentation(tenant, data)
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_invalid("验签过程发生内部错误")
        return
    if not valid:
        self._send_json(
            200, {"valid": False, "reason": reason or "验签失败"}
        )
        return

    presentation = data["presentation"]
    consumption_id = hashlib.sha256(
        crypto.canonicalize(data)
    ).hexdigest()
    try:
        consumed, consumed_at = store.consume_trust_presentation(
            tenant,
            presentation["issuer_did"],
            presentation["presentation_id"],
            consumption_id,
        )
    except StorageError:
        self._send_error(500, "存储失败")
        return
    if not consumed:
        self._send_json(
            200, {"valid": False, "reason": "外部演示已消费"}
        )
        return
    self._send_json(
        200,
        {
            "valid": True,
            "consumption_id": consumption_id,
            "consumed_at": consumed_at,
        },
    )

